 "unhealthy": "không tốt cho sức khỏe",
 "Unit 3 Birthday Party Lesson 1–2: one … twelve. How old are you? I'm seven. How many dolls? Two dolls.": "Unit 3 Tiệc sinh nhật, Unit 1–2: một … mười hai. Bạn mấy tuổi? Tớ bảy tuổi. Có bao nhiêu búp bê? Hai búp bê.",
 "Unit 4 Lesson 2, 4: I like juice. I don't like juice. What's this? This is pizza. I like pizza.": "Unit 4 Unit 2, 4: Con thích nước ép. Con không thích nước ép. Đây là gì? Đây là bánh pizza. Con thích pizza.",
 "Unit 4 Lesson 2, 4: juice, chicken, fish, ice cream, pizza, rice, cake, bread. I like juice. I don't like juice. Lesson 3: Here you are. Thank you. You're welcome.": "Unit 4 Unit 2, 4: nước ép, thịt gà, cá, kem, pizza, cơm, bánh ngọt, bánh mì. Con thích nước ép. Con không thích nước ép. Unit 3: Của bạn đây. Cảm ơn. Không có gì.",
 "Unit 5 Lesson 2: play soccer, jump rope, fly a kite, ride a bike. I can… I can't… · Unit 6 Lesson 4: run, hop, swim, walk": "Unit 5 Unit 2: đá bóng, nhảy dây, thả diều, đi xe đạp. Tớ biết… Tớ không biết… · Unit 6 Unit 4: chạy, nhảy lò cò, bơi, đi bộ",
 "Unit 5 Lesson 3: Please help me. Sure. (Be helpful) · Unit 6 Lesson 4: run, hop, swim, walk. Can zebras run? Yes, they can.": "Unit 5 Unit 3: Giúp tớ với. Được thôi. (Biết giúp đỡ) · Unit 6 Unit 4: chạy, nhảy lò cò, bơi, đi bộ. Ngựa vằn có chạy được không? Có, chúng chạy được.",
 "Unit 7 Lesson 4 Healthy Habits: wash my face, wash my hands, brush my hair, brush my teeth. I can wash my face.": "Unit 7 Unit 4 Thói quen tốt: rửa mặt, rửa tay, chải tóc, đánh răng. Con tự rửa mặt được.",
